import React, { useState } from 'react';
import { ThemeProvider } from './context/ThemeContext';
import Header from './components/Header';
import ChatWindow from './components/ChatWindow';
import InputBar from './components/InputBar';
import './App.css';

function App() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMessage = { sender: 'user', text: input };
    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setLoading(true);

    try {
      const res = await fetch('http://localhost:5000/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt: input })
      });

      const data = await res.json();
      const botMessage = { sender: 'bot', text: data.response };
      setMessages((prev) => [...prev, botMessage]);
    } catch {
      setMessages((prev) => [
        ...prev,
        { sender: 'bot', text: '⚠️ Could not fetch response.' },
      ]);
    }

    setLoading(false);
  };

  const handleDetect = async () => {
    if (!input.trim()) return;
  
    setLoading(true);
    try {
      const res = await fetch('http://localhost:5000/api/detect', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: input })
      });
  
      const data = await res.json();
      const resultMessage = {
        sender: 'bot',
        text: `🧪 Detection Result: ${data.result || 'Unclassified'}`
      };
  
      setMessages((prev) => [...prev, resultMessage]);
    } catch {
      setMessages((prev) => [...prev, {
        sender: 'bot',
        text: '⚠️ Detection failed.'
      }]);
    }
    setLoading(false);
  };
  

  return (
    <ThemeProvider>
      <div className="app">
        <Header />
        <ChatWindow messages={messages} loading={loading} />
        <InputBar input={input} setInput={setInput} onSend={sendMessage} />
      </div>
    </ThemeProvider>
  );
}

export default App;
